/* ============================================
   ClipCast Design System
   ============================================ */

/* CSS Variables */
:root {
  /* Brand Colors (from source_brief.md) */
  --cc-primary: #1868DB;
  --cc-primary-dark: #1457b8;
  --cc-accent: #FF613D;
  --cc-accent-dark: #e5532f;
  --cc-dark: #292A2E;
  --cc-dark-light: #3a3b40;

  /* Extended Palette */
  --cc-indigo: #6366F1;
  --cc-indigo-light: #818CF8;
  --cc-indigo-muted: #E0E7FF;
  --cc-purple: #8B5CF6;
  --cc-bg: #F8FAFC;
  --cc-bg-alt: #F1F5F9;
  --cc-surface: #FFFFFF;
  --cc-text: #1E293B;
  --cc-text-secondary: #64748B;
  --cc-text-muted: #94A3B8;
  --cc-border: #E2E8F0;
  --cc-border-light: #F1F5F9;
  --cc-success: #10B981;
  --cc-warning: #F59E0B;

  /* Typography */
  --font-heading: 'Inter', 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  /* Spacing Scale (8px base) */
  --space-1: 0.25rem;   /* 4px */
  --space-2: 0.5rem;    /* 8px */
  --space-3: 0.75rem;   /* 12px */
  --space-4: 1rem;      /* 16px */
  --space-5: 1.25rem;   /* 20px */
  --space-6: 1.5rem;    /* 24px */
  --space-8: 2rem;      /* 32px */
  --space-10: 2.5rem;   /* 40px */
  --space-12: 3rem;     /* 48px */
  --space-16: 4rem;     /* 64px */
  --space-20: 5rem;     /* 80px */
  --space-24: 6rem;     /* 96px */

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
  --shadow-glow: 0 0 20px rgb(99 102 241 / 0.3);

  /* Radius */
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;
  --radius-full: 9999px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 200ms ease;
  --transition-slow: 300ms ease;

  /* Z-index scale */
  --z-base: 0;
  --z-dropdown: 100;
  --z-sticky: 200;
  --z-fixed: 300;
  --z-modal-backdrop: 400;
  --z-modal: 500;
  --z-popover: 600;
  --z-toast: 700;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--cc-text);
  background-color: var(--cc-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img, svg, video {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

input, textarea, select {
  font-family: inherit;
  font-size: inherit;
}

ul, ol {
  list-style: none;
}

/* Utility Classes */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding-left: var(--space-6);
  padding-right: var(--space-6);
}

@media (min-width: 768px) {
  .container {
    padding-left: var(--space-8);
    padding-right: var(--space-8);
  }
}

@media (min-width: 1024px) {
  .container {
    padding-left: var(--space-12);
    padding-right: var(--space-12);
  }
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ============================================
   Typography
   ============================================ */

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
  color: var(--cc-dark);
}

.text-display {
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.text-h1 {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
}

.text-h2 {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 700;
}

.text-h3 {
  font-size: clamp(1.25rem, 2vw, 1.5rem);
  font-weight: 600;
}

.text-h4 {
  font-size: 1.125rem;
  font-weight: 600;
}

.text-body {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--cc-text-secondary);
}

.text-body-lg {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--cc-text-secondary);
}

.text-small {
  font-size: 0.875rem;
  line-height: 1.5;
  color: var(--cc-text-muted);
}

.text-label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* ============================================
   Buttons
   ============================================ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
  cursor: pointer;
  white-space: nowrap;
  min-height: 44px;
}

.btn-primary {
  background: linear-gradient(135deg, var(--cc-primary) 0%, var(--cc-indigo) 100%);
  color: white;
  box-shadow: var(--shadow-md);
}

.btn-primary:hover {
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg), var(--shadow-glow);
}

.btn-primary:active {
  transform: translateY(0);
}

.btn-accent {
  background: var(--cc-accent);
  color: white;
  box-shadow: var(--shadow-md);
}

.btn-accent:hover {
  background: var(--cc-accent-dark);
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn-secondary {
  background: white;
  color: var(--cc-text);
  border: 1.5px solid var(--cc-border);
  box-shadow: var(--shadow-sm);
}

.btn-secondary:hover {
  border-color: var(--cc-primary);
  color: var(--cc-primary);
  box-shadow: var(--shadow-md);
}

.btn-ghost {
  background: transparent;
  color: var(--cc-text-secondary);
}

.btn-ghost:hover {
  color: var(--cc-primary);
  background: var(--cc-indigo-muted);
}

.btn-lg {
  padding: var(--space-4) var(--space-8);
  font-size: 1rem;
  border-radius: var(--radius-xl);
}

.btn-sm {
  padding: var(--space-2) var(--space-4);
  font-size: 0.875rem;
  border-radius: var(--radius-md);
}

/* ============================================
   Cards
   ============================================ */

.card {
  background: var(--cc-surface);
  border-radius: var(--radius-xl);
  border: 1px solid var(--cc-border);
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
  overflow: hidden;
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card-body {
  padding: var(--space-6);
}

/* ============================================
   Forms
   ============================================ */

.form-input {
  width: 100%;
  padding: var(--space-3) var(--space-4);
  font-size: 1rem;
  color: var(--cc-text);
  background: white;
  border: 1.5px solid var(--cc-border);
  border-radius: var(--radius-lg);
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
  min-height: 48px;
}

.form-input:focus {
  outline: none;
  border-color: var(--cc-primary);
  box-shadow: 0 0 0 3px rgb(24 104 219 / 0.15);
}

.form-input::placeholder {
  color: var(--cc-text-muted);
}

.form-label {
  display: block;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--cc-text);
  margin-bottom: var(--space-2);
}

/* ============================================
   Navigation
   ============================================ */

.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: var(--z-fixed);
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(226, 232, 240, 0.6);
  transition: box-shadow var(--transition-base);
}

.navbar.scrolled {
  box-shadow: var(--shadow-md);
}

.navbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--cc-dark);
}

.nav-logo-icon {
  width: 32px;
  height: 32px;
  background: linear-gradient(135deg, var(--cc-primary) 0%, var(--cc-indigo) 100%);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
}

.nav-links {
  display: none;
  align-items: center;
  gap: var(--space-1);
}

@media (min-width: 768px) {
  .nav-links {
    display: flex;
  }
}

.nav-link {
  padding: var(--space-2) var(--space-3);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--cc-text-secondary);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.nav-link:hover {
  color: var(--cc-primary);
  background: var(--cc-indigo-muted);
}

.nav-link.active {
  color: var(--cc-primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.nav-mobile-toggle {
  display: flex;
  padding: var(--space-2);
  color: var(--cc-text);
}

@media (min-width: 768px) {
  .nav-mobile-toggle {
    display: none;
  }
}

/* Mobile Menu */
.nav-mobile-menu {
  display: none;
  position: absolute;
  top: 64px;
  left: 0;
  right: 0;
  background: white;
  border-bottom: 1px solid var(--cc-border);
  padding: var(--space-4);
  box-shadow: var(--shadow-lg);
}

.nav-mobile-menu.open {
  display: block;
}

.nav-mobile-menu .nav-link {
  display: block;
  padding: var(--space-3) var(--space-4);
  border-radius: var(--radius-md);
}

/* ============================================
   Sections
   ============================================ */

.section {
  padding-top: var(--space-20);
  padding-bottom: var(--space-20);
}

.section-sm {
  padding-top: var(--space-16);
  padding-bottom: var(--space-16);
}

.section-header {
  text-align: center;
  max-width: 768px;
  margin: 0 auto var(--space-12);
}

.section-header h2 {
  margin-bottom: var(--space-4);
}

.section-header p {
  font-size: 1.125rem;
  color: var(--cc-text-secondary);
}

/* ============================================
   Hero
   ============================================ */

.hero {
  position: relative;
  padding-top: calc(64px + var(--space-20));
  padding-bottom: var(--space-20);
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  background: linear-gradient(135deg, #F0F4FF 0%, #F8FAFC 50%, #FFF0EB 100%);
}

.hero-bg::before {
  content: '';
  position: absolute;
  top: -20%;
  right: -10%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(99, 102, 241, 0.12) 0%, transparent 70%);
  border-radius: 50%;
}

.hero-bg::after {
  content: '';
  position: absolute;
  bottom: -10%;
  left: -5%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(255, 97, 61, 0.08) 0%, transparent 70%);
  border-radius: 50%;
}

.hero-inner {
  position: relative;
  z-index: 1;
}

.hero-content {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  background: white;
  border: 1px solid var(--cc-border);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--cc-text-secondary);
  margin-bottom: var(--space-6);
  box-shadow: var(--shadow-sm);
}

.hero-badge .badge-dot {
  width: 8px;
  height: 8px;
  background: var(--cc-accent);
  border-radius: 50%;
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

.hero h1 {
  margin-bottom: var(--space-6);
}

.hero h1 .gradient-text {
  background: linear-gradient(135deg, var(--cc-primary) 0%, var(--cc-indigo) 50%, var(--cc-purple) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-description {
  font-size: 1.125rem;
  color: var(--cc-text-secondary);
  max-width: 560px;
  margin: 0 auto var(--space-8);
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
}

/* ============================================
   Logo Bar
   ============================================ */

.logo-bar {
  padding-top: var(--space-12);
  padding-bottom: var(--space-12);
  background: white;
  border-top: 1px solid var(--cc-border);
  border-bottom: 1px solid var(--cc-border);
}

.logo-bar-text {
  text-align: center;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--cc-text-muted);
  margin-bottom: var(--space-8);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.logo-bar-grid {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: var(--space-8) var(--space-12);
}

.logo-item {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--cc-text-muted);
  opacity: 0.6;
  transition: opacity var(--transition-fast);
}

.logo-item:hover {
  opacity: 1;
  color: var(--cc-text);
}

/* ============================================
   Feature Cards
   ============================================ */

.feature-grid {
  display: grid;
  gap: var(--space-6);
}

@media (min-width: 640px) {
  .feature-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .feature-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.feature-grid-4 {
  display: grid;
  gap: var(--space-6);
}

@media (min-width: 640px) {
  .feature-grid-4 {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .feature-grid-4 {
    grid-template-columns: repeat(4, 1fr);
  }
}

.feature-card {
  background: white;
  border-radius: var(--radius-xl);
  border: 1px solid var(--cc-border);
  padding: var(--space-6);
  transition: all var(--transition-base);
}

.feature-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
  border-color: var(--cc-indigo-muted);
}

.feature-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-4);
}

.feature-icon.blue {
  background: linear-gradient(135deg, #DBEAFE 0%, #BFDBFE 100%);
  color: var(--cc-primary);
}

.feature-icon.purple {
  background: linear-gradient(135deg, #E0E7FF 0%, #C7D2FE 100%);
  color: var(--cc-indigo);
}

.feature-icon.orange {
  background: linear-gradient(135deg, #FFEDD5 0%, #FED7AA 100%);
  color: var(--cc-accent);
}

.feature-icon.green {
  background: linear-gradient(135deg, #D1FAE5 0%, #A7F3D0 100%);
  color: var(--cc-success);
}

.feature-card h3 {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.feature-card p {
  font-size: 0.9375rem;
  color: var(--cc-text-secondary);
  line-height: 1.6;
}

/* ============================================
   Stats
   ============================================ */

.stats-grid {
  display: grid;
  gap: var(--space-8);
  text-align: center;
}

@media (min-width: 640px) {
  .stats-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.stat-number {
  font-size: clamp(2.5rem, 5vw, 3.5rem);
  font-weight: 800;
  background: linear-gradient(135deg, var(--cc-primary) 0%, var(--cc-indigo) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  line-height: 1;
  margin-bottom: var(--space-3);
}

.stat-label {
  font-size: 1rem;
  font-weight: 500;
  color: var(--cc-text-secondary);
}

/* ============================================
   Testimonials
   ============================================ */

.testimonial-card {
  background: white;
  border-radius: var(--radius-xl);
  border: 1px solid var(--cc-border);
  padding: var(--space-8);
  box-shadow: var(--shadow-sm);
}

.testimonial-quote {
  font-size: 1.0625rem;
  line-height: 1.7;
  color: var(--cc-text);
  margin-bottom: var(--space-6);
  font-style: italic;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.testimonial-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--cc-primary) 0%, var(--cc-indigo) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: 600;
  font-size: 0.875rem;
  flex-shrink: 0;
}

.testimonial-name {
  font-weight: 600;
  color: var(--cc-dark);
  font-size: 0.9375rem;
}

.testimonial-role {
  font-size: 0.875rem;
  color: var(--cc-text-muted);
}

/* ============================================
   Pricing
   ============================================ */

.pricing-toggle {
  display: inline-flex;
  align-items: center;
  background: white;
  border: 1.5px solid var(--cc-border);
  border-radius: var(--radius-full);
  padding: 4px;
  gap: 4px;
  margin-bottom: var(--space-8);
}

.pricing-toggle button {
  padding: var(--space-2) var(--space-5);
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  color: var(--cc-text-secondary);
  transition: all var(--transition-fast);
}

.pricing-toggle button.active {
  background: linear-gradient(135deg, var(--cc-primary) 0%, var(--cc-indigo) 100%);
  color: white;
  box-shadow: var(--shadow-sm);
}

.pricing-badge {
  display: inline-flex;
  align-items: center;
  padding: var(--space-1) var(--space-3);
  background: linear-gradient(135deg, #D1FAE5 0%, #A7F3D0 100%);
  color: #065F46;
  font-size: 0.75rem;
  font-weight: 700;
  border-radius: var(--radius-full);
  margin-left: var(--space-2);
}

.pricing-grid {
  display: grid;
  gap: var(--space-6);
  align-items: start;
}

@media (min-width: 768px) {
  .pricing-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .pricing-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.pricing-card {
  background: white;
  border-radius: var(--radius-xl);
  border: 1.5px solid var(--cc-border);
  padding: var(--space-6);
  transition: all var(--transition-base);
  position: relative;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.pricing-card.popular {
  border-color: var(--cc-indigo);
  box-shadow: 0 0 0 1px var(--cc-indigo), var(--shadow-lg);
}

.pricing-card.popular::before {
  content: 'MOST POPULAR';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  padding: var(--space-1) var(--space-4);
  background: linear-gradient(135deg, var(--cc-primary) 0%, var(--cc-indigo) 100%);
  color: white;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  border-radius: var(--radius-full);
}

.pricing-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: var(--space-2);
}

.pricing-price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--cc-dark);
  line-height: 1;
  margin-bottom: var(--space-1);
}

.pricing-price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--cc-text-muted);
}

.pricing-period {
  font-size: 0.875rem;
